decls:
--category-edge-color:var(
    --steamawards-category-edge-color,
    color-mix(
      in oklab,
      var(--steamawards-category-color),
      black var(--steamawards-category-edge-darken, 50%)
    )
  )

box-shadow:calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.125)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.125) 0
      var(--category-edge-color),
    calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.25)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.25) 0
      var(--category-edge-color),
    calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.375)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.375) 0
      var(--category-edge-color),
    calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.5)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.5) 0
      var(--category-edge-color),
    calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.625)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.625) 0
      var(--category-edge-color),
    calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.75)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.75) 0
      var(--category-edge-color),
    calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.875)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 0.875) 0
      var(--category-edge-color),
    calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 1)
      calc(calc(0.08 * clamp(36px, 6vw, 76px)) * 1) 0 var(--category-edge-color)

